def grade_from_score(score):
    try:
        value = max(0, min(100, int(round(float(score)))))
    except (TypeError, ValueError):
        value = 0
    for low, high, grade in GRADE_SLABS:
        if low <= value <= high:
            return grade
    return "E Grade"

