def _safe_subprocess_env():
    """Return a subprocess environment with a compact, de-duplicated PATH.

    Some long-running Streamlit processes can inherit an oversized PATH from
    earlier reruns/deployments. Passing a compact PATH to media tools prevents
    execve from failing with E2BIG ("Argument list too long").
    """
    source_env = os.environ
    raw_path = source_env.get("PATH", "")
    preferred = ["/usr/local/bin", "/usr/bin", "/bin", "/opt/homebrew/bin"]
    seen = set()
    compact = []
    for entry in preferred + raw_path.split(os.pathsep):
        entry = entry.strip()
        if entry and entry not in seen:
            seen.add(entry)
            compact.append(entry)
    # Media decoding does not need the full application environment (which can
    # contain API secrets and oversized variables). Keep only runtime essentials.
    env = {"PATH": os.pathsep.join(compact)}
    for key in ("HOME", "LANG", "LC_ALL", "TMPDIR", "LD_LIBRARY_PATH"):
        value = source_env.get(key)
        if value and len(value) < 4096:
            env[key] = value
    return env


def _ffmpeg_extract_gd_audio(video_path):
    """Extract compact mono MP3 audio from an uploaded GD video.

    Returns the temporary audio path on success, otherwise raises a readable
    RuntimeError so the UI can show the real failure rather than a generic
    extraction message.
    """
    ffmpeg = shutil.which("ffmpeg", path=_safe_subprocess_env().get("PATH", ""))
    if not ffmpeg:
        raise RuntimeError("FFmpeg executable was not found in the deployment environment.")

    if not video_path or not os.path.isfile(video_path):
        raise RuntimeError("The uploaded GD video file is missing or could not be saved.")

    out = tempfile.NamedTemporaryFile(delete=False, suffix="_gd_audio.mp3")
    out_path = out.name
    out.close()
    # Keep speech intelligibility high for Indian English, names and MBA vocabulary.
    # 24 kHz / 96 kbps is still compact for the 25 MB API limit, but less lossy
    # than the earlier 16 kHz / 64 kbps extraction. Loudness normalisation helps
    # when students sit at different distances from the microphone.
    cmd = [
        ffmpeg, "-hide_banner", "-nostdin", "-y", "-i", str(video_path),
        "-vn", "-ac", "1", "-ar", "24000",
        "-af", "loudnorm=I=-18:TP=-2:LRA=11",
        "-codec:a", "libmp3lame", "-b:a", "96k",
        out_path
    ]
    try:
        result = subprocess.run(
            cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
            text=True, timeout=300, env=_safe_subprocess_env()
        )
        if result.returncode != 0:
            detail = (result.stderr or "").strip().splitlines()
            detail = " | ".join(detail[-4:])[-1200:]
            raise RuntimeError("FFmpeg could not extract audio" + (f": {detail}" if detail else f" (exit code {result.returncode})"))
        if not os.path.isfile(out_path) or os.path.getsize(out_path) == 0:
            raise RuntimeError("FFmpeg finished but produced an empty audio file. Check that the video contains an audio track.")
        return out_path
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("Audio extraction timed out after 5 minutes. Try a shorter or smaller video.") from exc
    except OSError as exc:
        if getattr(exc, "errno", None) == 7:
            raise RuntimeError("FFmpeg could not start because the process environment is too large. The app will retry with a compact PATH; if this persists, restart the Streamlit app and inspect its environment.") from exc
        raise RuntimeError(f"Could not start FFmpeg: {exc}") from exc
    finally:
        # Keep the output only after successful extraction; clean up on failures.
        if os.path.exists(out_path):
            try:
                if os.path.getsize(out_path) == 0:
                    os.remove(out_path)
            except OSError:
                pass


def transcribe_gd_with_diarization(audio_path):
    """Use OpenAI's speaker-diarized transcription when configured."""
    if not openai_client:
        return None, "OPENAI_API_KEY is not configured. Add it to Streamlit Secrets for multi-speaker GD analysis."
    try:
        size_mb = os.path.getsize(audio_path) / (1024 * 1024)
        if size_mb > 24.5:
            return None, "The extracted GD audio is still above the 25 MB transcription limit."
        with open(audio_path, "rb") as audio_file:
            result = openai_client.audio.transcriptions.create(
                model="gpt-4o-transcribe-diarize",
                file=audio_file,
                response_format="diarized_json",
                chunking_strategy="auto",
                # The GD is conducted in English. An explicit language hint can
                # improve recognition/latency; this model does not accept prompt
                # or keywords, so do not pass unsupported context parameters.
                language="en",
            )
        raw = result.model_dump() if hasattr(result, "model_dump") else dict(result)
        segments = raw.get("segments") or []
        clean = []
        for seg in segments:
            speaker = str(seg.get("speaker") or "speaker_0")
            phrase = str(seg.get("text") or "").strip()
            if not phrase:
                continue
            clean.append({
                "speaker": speaker,
                "start": round(float(seg.get("start") or 0), 2),
                "end": round(float(seg.get("end") or 0), 2),
                "text": phrase
            })
        if not clean:
            return None, "No clear human speech was detected in the GD recording."
        return clean, None
    except Exception as exc:
        return None, f"GD transcription failed: {exc}"


def _format_gd_transcript(segments, speaker_map=None):
    speaker_map = speaker_map or {}
    lines = []
    for seg in segments:
        speaker = speaker_map.get(seg["speaker"], seg["speaker"])
        lines.append(f"[{seg['start']:.1f}-{seg['end']:.1f}s] {speaker}: {seg['text']}")
    return "\n".join(lines)


def _extract_gd_self_introductions(text):
    """Return clean names explicitly spoken in common self-introduction phrases."""
    text = str(text or "")
    patterns = [
        r"\bmy name is\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})(?=\s*(?:[,.;!?]|$)|\s+and\s+my\s+scholar\s+id\b)",
        r"\bI\s+am\s+([A-Z][a-z]+(?:[ '-][A-Z][a-z]+){0,3})(?=\s*(?:[,.;!?]|$)|\s*,?\s*(?:pursuing|currently|from|doing|studying|a|an|the|and|with|at)\b)",
        r"\bI['’]?m\s+([A-Z][a-z]+(?:[ '-][A-Z][a-z]+){0,3})(?=\s*(?:[,.;!?]|$)|\s*,?\s*(?:pursuing|currently|from|doing|studying|a|an|the|and|with|at)\b)",
        r"\bmyself\s+is\s+([A-Z][a-z]+(?:[ '-][A-Z][a-z]+){0,3})\b",
    ]
    found = []
    stop_words = {
        "and", "currently", "pursuing", "studying", "doing", "from", "at", "in",
        "with", "who", "which", "working", "work", "a", "an", "the", "my",
        "i", "we", "our", "have", "has", "is", "am", "was", "are", "also",
        "basically", "first", "second", "semester", "mba", "bba", "bcom",
    }
    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.I):
            raw_name = re.sub(r"\s+", " ", match.group(1)).strip(" .,'-")
            tokens = raw_name.split()
            clean_tokens = []
            for token in tokens:
                if token.strip(" .,'-!?;:").casefold() in stop_words:
                    break
                clean_tokens.append(token.strip(" .,'-!?;:"))
            name = " ".join(token for token in clean_tokens if token).strip()
            if name and name.casefold() not in {"good", "thank", "technology", "everyone", "agree"}:
                if name.casefold() not in {n.casefold() for n in found}:
                    found.append(name)
    return found


def _is_gd_greeting_boundary(text):
    """Detect a greeting only when it opens a new diarised contribution."""
    value = re.sub(r"\s+", " ", str(text or "").strip())
    # Permit brief discourse fillers before a greeting, but never match greetings
    # buried later in a sentence (which may be casual conversation).
    value = re.sub(r"^(?:(?:okay|ok|so|well|uh|um|right)[,.\s-]+){1,3}", "", value, flags=re.I)
    return bool(re.match(
        r"^(?:good\s+(?:morning|afternoon|evening)(?:\s+(?:everyone|all|guys|friends))?"
        r"|hello(?:\s+(?:everyone|all|guys|friends))?"
        r"|hi(?:\s+(?:everyone|all|guys|friends))?"
        r"|hey(?:\s+(?:everyone|all|guys|friends))?"
        r"|greetings(?:\s+(?:everyone|all))?)"
        r"(?=$|[\s,!.?])",
        value,
        flags=re.I,
    ))


def split_gd_segments_on_conflicting_introductions(segments):
    """Create provisional speaker boundaries from conflicting introductions or greetings.

    Explicit self-introductions are the primary identity anchor. A greeting at the
    beginning of a contribution is a fallback boundary when no self-introduction
    occurs within 30 seconds. This is transcript-guided repair, not acoustic proof.
    Original wording and timestamps are preserved; only display speaker IDs change.
    """
    segments = [dict(seg) for seg in (segments or [])]
    events_by_speaker = {}
    for position, seg in enumerate(segments):
        sid = str(seg.get("speaker") or "speaker_0")
        start = float(seg.get("start") or 0)
        text = str(seg.get("text") or "")
        for name in _extract_gd_self_introductions(text):
            events_by_speaker.setdefault(sid, []).append(
                {"start": start, "position": position, "kind": "intro",
                 "name": name, "norm": name.casefold()}
            )
        if _is_gd_greeting_boundary(text):
            events_by_speaker.setdefault(sid, []).append(
                {"start": start, "position": position, "kind": "greeting",
                 "name": "", "norm": ""}
            )

    split_events = {}
    notes = []
    for sid, events in events_by_speaker.items():
        events.sort(key=lambda event: (event["start"], event["position"]))
        intros = [event for event in events if event["kind"] == "intro"]
        greetings = [event for event in events if event["kind"] == "greeting"]

        # Preserve the original conflicting-introduction rule.
        seen_names = set()
        for event in intros:
            norm = event["norm"]
            if seen_names and norm not in seen_names:
                split_events.setdefault(sid, []).append(
                    (event["start"], event["position"], "self-introduction", event["name"])
                )
            seen_names.add(norm)

        # A greeting is a fallback only when no explicit introduction is close
        # enough to belong to the same opening contribution. The earliest marker
        # (greeting or introduction) establishes the initial identity; later
        # greeting-led contributions can create provisional boundaries.
        identity_markers = sorted(
            events, key=lambda event: (event["start"], event["position"])
        )
        first_marker = (
            (identity_markers[0]["start"], identity_markers[0]["position"])
            if identity_markers else None
        )
        for greeting in greetings:
            nearby_intro = any(
                abs(intro["start"] - greeting["start"]) <= 30.0
                for intro in intros
            )
            marker = (greeting["start"], greeting["position"])
            if nearby_intro or first_marker is None or marker <= first_marker:
                continue
            split_events.setdefault(sid, []).append(
                (greeting["start"], greeting["position"], "greeting", "")
            )

    if not split_events:
        for seg in segments:
            sid = str(seg.get("speaker") or "speaker_0")
            seg.setdefault("original_speaker", sid)
        return segments, []

    # Deduplicate boundaries at the same segment/timestamp (e.g. a greeting and
    # an introduction spoken in the same opening turn).
    for sid, events in list(split_events.items()):
        unique = {}
        for start, position, kind, name in sorted(events, key=lambda item: (item[0], item[1])):
            key = (round(start, 2), position)
            if key not in unique:
                unique[key] = (start, position, kind, name)
            elif kind == "self-introduction":
                unique[key] = (start, position, kind, name)
        split_events[sid] = sorted(unique.values(), key=lambda item: (item[0], item[1]))

    counters = {sid: len(events) for sid, events in split_events.items()}
    active_index = {}
    result = []
    for position, original in enumerate(segments):
        seg = dict(original)
        sid = str(seg.get("speaker") or "speaker_0")
        seg.setdefault("original_speaker", sid)
        if sid in split_events:
            for idx, (split_start, split_position, kind, name) in enumerate(split_events[sid], 1):
                if (float(seg.get("start") or 0), position) >= (split_start, split_position):
                    active_index[sid] = idx
            if sid in active_index:
                seg["speaker"] = f"{sid}_split_{active_index[sid]}"
        result.append(seg)

    for sid, events in split_events.items():
        for idx, (start, position, kind, name) in enumerate(events, 1):
            if kind == "greeting":
                notes.append(
                    f"{sid} was split at {start:.1f}s using a greeting as a fallback identity boundary."
                )
            else:
                notes.append(
                    f"{sid} was split at {start:.1f}s for the self-introduction '{name}'."
                )
    return result, notes


def detect_gd_speaker_identity_conflicts(segments):
    """Flag unsafe speaker/name collisions before any individual grade is generated.

    A diarisation ID that contains two distinct explicit self-introductions is
    unresolved. Also flag an exact full name introduced under multiple IDs, which
    can indicate that one real participant was split into multiple diarisation IDs.
    This is a safety check, not a claim that names alone prove speaker identity.
    """
    by_speaker = {}
    by_name = {}
    for seg in segments or []:
        sid = str(seg.get("speaker") or "speaker_0")
        for name in _extract_gd_self_introductions(seg.get("text", "")):
            norm = re.sub(r"\s+", " ", name).strip().casefold()
            by_speaker.setdefault(sid, {})[norm] = name
            by_name.setdefault(norm, set()).add(sid)

    conflicts = {}
    for sid, names in by_speaker.items():
        if len(names) > 1:
            conflicts[sid] = list(names.values())

    for norm, speaker_ids in by_name.items():
        if len(speaker_ids) > 1:
            display_name = next(
                (name for names in by_speaker.values() for key, name in names.items() if key == norm),
                norm,
            )
            for sid in speaker_ids:
                existing = conflicts.setdefault(sid, [])
                label = f"{display_name} (also introduced under another speaker ID)"
                if label not in existing:
                    existing.append(label)
    return conflicts


def _normalise_gd_person_name(value):
    """Normalise a spoken/roster name for conservative exact matching."""
    value = unicodedata.normalize("NFKD", str(value or ""))
    value = "".join(ch for ch in value if not unicodedata.combining(ch))
    value = re.sub(r"[^A-Za-z0-9 ]+", " ", value).casefold()
    return re.sub(r"\s+", " ", value).strip()


def auto_match_gd_speakers_to_roster(segments, conflicted_speakers=None):
    """Map a diarised speaker to a student only on a unique exact name match.

    The name must come from that speaker's own explicit introduction and match
    exactly one active roster/student record. No voice, order, LLM or fuzzy-name
    guess is used. Ambiguous or absent matches remain unresolved.
    """
    conflicted_speakers = set(conflicted_speakers or [])
    intros = {}
    for seg in segments or []:
        sid = str(seg.get("speaker") or "speaker_0")
        for name in _extract_gd_self_introductions(seg.get("text", "")):
            intros.setdefault(sid, {})[_normalise_gd_person_name(name)] = name

    conn = get_db_connection()
    try:
        rows = []
        try:
            rows.extend(dict(r) for r in conn.execute(
                "SELECT scholar_id, full_name AS full_name FROM student_roster WHERE active=1"
            ).fetchall())
        except Exception:
            pass
        try:
            rows.extend(dict(r) for r in conn.execute(
                "SELECT scholar_id, TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS full_name FROM students"
            ).fetchall())
        except Exception:
            pass
    finally:
        conn.close()

    by_name = {}
    for row in rows:
        name_key = _normalise_gd_person_name(row.get("full_name"))
        scholar_id = str(row.get("scholar_id") or "").strip().upper()
        if name_key and scholar_id:
            by_name.setdefault(name_key, {})[scholar_id] = str(row.get("full_name") or "").strip()

    matched = {}
    for sid, names in intros.items():
        if sid in conflicted_speakers or len(names) != 1:
            continue
        name_key, spoken_name = next(iter(names.items()))
        candidates = by_name.get(name_key, {})
        if len(candidates) == 1:
            scholar_id, roster_name = next(iter(candidates.items()))
            matched[sid] = {"scholar_id": scholar_id, "name": roster_name or spoken_name}
    return matched


def identify_gd_speaker_names(segments, fallback_map):
    """Identify names from explicit introductions first; use the LLM only as support."""
    speaker_ids = list(dict.fromkeys(str(seg.get("speaker") or "speaker_0") for seg in segments))
    intro_names = {}
    for seg in segments:
        sid = str(seg.get("speaker") or "speaker_0")
        for name in _extract_gd_self_introductions(seg.get("text", "")):
            intro_names.setdefault(sid, [])
            if name.casefold() not in {x.casefold() for x in intro_names[sid]}:
                intro_names[sid].append(name)

    # Deterministic self-introductions outrank any model-generated guess.
    resolved = dict(fallback_map)
    used = set()
    for sid in speaker_ids:
        names = intro_names.get(sid, [])
        if len(names) == 1 and names[0].casefold() not in used:
            resolved[sid] = names[0]
            used.add(names[0].casefold())

    if not client or not segments:
        return resolved, "Explicit self-introductions were used where available; uncertain identities remain speaker-labelled."

    chronological = [
        {"speaker_id": str(seg.get("speaker") or "speaker_0"),
         "start": round(float(seg.get("start") or 0), 2),
         "text": str(seg.get("text") or "").strip()}
        for seg in segments if str(seg.get("text") or "").strip()
    ]
    prompt = f"""
Identify speakers in this chronological MBA group discussion transcript. Use an exact self-introduction
when present. A moderator's direct address may be used only if the next response clearly belongs to that
person. Do not treat moderator as a student, do not infer from voice/accent/topic, and do not add words to
names. Do not assign the same name to multiple speaker IDs. For any ID with an explicit self-introduction,
copy only the introduced name exactly. Return ONLY JSON: {{"names": {{"speaker_id": "full name or empty string"}}}}

CHRONOLOGICAL TURNS:
{json.dumps(chronological, ensure_ascii=False)}
"""
    try:
        raw = client.chat.completions.create(
            model=GROQ_MODEL,
            messages=[
                {"role": "system", "content": "Extract transcript-supported personal names only. Never fabricate or embellish a name. Return JSON only."},
                {"role": "user", "content": prompt},
            ],
            temperature=0,
        ).choices[0].message.content or ""
        clean = raw.replace("```json", "").replace("```", "").strip()
        parsed = json.loads(clean)
        names = parsed.get("names", {}) if isinstance(parsed, dict) else {}
        for sid in speaker_ids:
            if sid in intro_names:
                # Never let the LLM overwrite a deterministic intro or resolve multiple intros by guessing.
                continue
            candidate = re.sub(r"\s+", " ", str(names.get(sid, "") or "")).strip(" .,:;-'\"\n\t")
            # Only accept short name-like output, not trailing transcript fragments.
            if candidate and len(candidate) <= 50 and re.fullmatch(r"[A-Za-z]+(?:[ '-][A-Za-z]+){0,3}", candidate):
                norm = candidate.casefold()
                if norm not in used:
                    resolved[sid] = candidate
                    used.add(norm)
        identified = sum(1 for sid in speaker_ids if resolved.get(sid, "").casefold() != str(fallback_map.get(sid, "")).casefold())
        return resolved, f"Names identified for {identified} of {len(speaker_ids)} speaker IDs; explicit self-introductions take priority."
    except Exception:
        return resolved, "Explicit self-introductions were used where available; AI name matching was unavailable."


def _gd_speaker_stats(segments, speaker_map=None):
    speaker_map = speaker_map or {}
    stats = {}
    for seg in segments:
        key = speaker_map.get(seg["speaker"], seg["speaker"])
        words = re.findall(r"\b[\w']+\b", seg["text"])
        duration = max(0.0, seg["end"] - seg["start"])
        entry = stats.setdefault(key, {"speaking_seconds": 0.0, "words": 0, "turns": 0, "filler_words": 0})
        entry["speaking_seconds"] += duration
        entry["words"] += len(words)
        entry["turns"] += 1
        filler_pattern = r"\b(um+|uh+|er+|you know|like|basically|actually|i mean|kind of|sort of)\b"
        entry["filler_words"] += len(re.findall(filler_pattern, seg["text"], flags=re.I))
    total = sum(v["speaking_seconds"] for v in stats.values()) or 1.0
    for v in stats.values():
        v["participation_share_pct"] = round((v["speaking_seconds"] / total) * 100, 1)
        minutes = v["speaking_seconds"] / 60
        v["wpm"] = round(v["words"] / minutes, 1) if minutes else 0
    return stats


def generate_gd_video_assessment(topic, participants, transcript_text, stats):
    prompt = f"""
You are a rigorous MBA Group Discussion evaluator for IPER Bhopal.

GD TOPIC:
{topic}

PARTICIPANTS:
{json.dumps(participants, ensure_ascii=False)}

OBJECTIVE SPEAKER STATISTICS:
{json.dumps(stats, ensure_ascii=False)}

DIARIZED TRANSCRIPT:
{transcript_text}

Evaluate ONLY what is supported by the transcript and objective statistics. Never invent facts, gestures, facial expressions, confidence, tone, eye contact, or knowledge that is not evidenced. Background music/noise is not speech. If a speaker has little or no transcript evidence, say so and do not fabricate a score.

For each participant evaluate:
- Participation: speaking share, number of meaningful interventions, balance, whether contributions add value. Treat natural, relevant interruptions, respectful interjections, counter-arguments and building on another speaker's point as legitimate GD behaviour; do not penalise an interruption merely because it overlaps another turn. Penalise repeated disruptive cutting-off, domination or preventing others from contributing only when the transcript provides evidence. When overlapping turns make attribution unclear, do not assign the words to a specific participant or use them as individual evidence.
- Communication: English fluency, grammar, vocabulary, clarity, filler words, rate of speech based on transcript/timestamps. This is an English-medium placement assessment: Hindi/Hinglish code-switching is a communication weakness and should reduce the communication assessment. Do not penalize Indian English accent alone.
- Knowledge: relevance, factual/business awareness, examples, depth, understanding of the topic.
- Analytical Thinking: reasoning, cause-effect, comparison, trade-offs, originality.
- Listening & Team Behaviour: building on others, respectful disagreement, avoiding repetition/dominance, inviting others when evidenced.
- Leadership: initiative, structuring the discussion, synthesising ideas, moving toward conclusion when evidenced.
- Overall GD readiness.

Also evaluate the group as a whole:
- Topic handling
- Quality of discussion
- Balance of participation
- Depth of arguments
- Team dynamics
- Conclusion
- Overall group score

Grading calibration for this assessment:
- E — Needs Significant Improvement (internal 0–20): inadequate evidence, seriously weak or fundamentally incorrect performance.
- D — Limited Placement Readiness (internal 21–40): weak performance with substantial gaps.
- C — Developing Placement Readiness (internal 41–60): basic/partial performance with noticeable weaknesses.
- B — Good Placement Readiness (internal 61–80): placement-ready performance that is clearly demonstrated, consistent and accurate; award only when evidence supports it.
- A — Strong Placement Readiness (internal 81–100): exceptional, highly consistent and unusually strong performance; very rare.
Do not let fluent English, confidence, speaking volume, or business buzzwords compensate for weak substance.

Return ONLY valid JSON in this exact structure. Every participant object MUST include the exact diarisation SpeakerID from PARTICIPANTS; never infer or change it, and never identify a participant by array position:
{{
  "GroupAssessment": {{
    "OverallScore": 0,
    "TopicHandling": 0,
    "DiscussionQuality": 0,
    "ParticipationBalance": 0,
    "TeamDynamics": 0,
    "ConclusionQuality": 0,
    "Strengths": [],
    "Improvements": []
  }},
  "Participants": [
    {{
      "SpeakerID": "",
      "Name": "",
      "ParticipationScore": 0,
      "CommunicationScore": 0,
      "KnowledgeScore": 0,
      "AnalyticalThinkingScore": 0,
      "ListeningTeamworkScore": 0,
      "LeadershipScore": 0,
      "OverallScore": 0,
      "SpeakingTimeSeconds": 0,
      "ParticipationSharePercent": 0,
      "Interventions": 0,
      "WPM": 0,
      "FillerWords": 0,
      "Strengths": [],
      "AreasToImprove": [],
      "Evidence": [],
      "PlacementReadiness": "",
      "NextGDActionPlan": []
    }}
  ]
}}

Be deliberately strict. Do not reward fluency, length, confidence or business buzzwords without evidence. A strong B-level performance must be clearly demonstrated and A-level performance must be exceptional and rare; use the readiness labels rather than exposing numeric marks to students. Hindi/Hinglish usage in the English-medium assessment should materially reduce CommunicationScore. Return internal numeric scores for calculation only; the portal will display grades, never marks.
"""
    raw = get_groq_response(prompt)

    def _parse_report_json(value):
        """Parse a model response that may include a Markdown fence or surrounding text."""
        if not isinstance(value, str):
            raise ValueError("The AI response was empty or not text.")
        clean = value.strip()
        clean = re.sub(r"^```(?:json)?\s*", "", clean, flags=re.IGNORECASE)
        clean = re.sub(r"\s*```$", "", clean)
        # First try the full response, then decode the first JSON object if extra text exists.
        try:
            parsed = json.loads(clean)
        except json.JSONDecodeError:
            start = clean.find("{")
            if start < 0:
                raise
            parsed, _end = json.JSONDecoder().raw_decode(clean[start:])
        if not isinstance(parsed, dict):
            raise ValueError("The AI response did not contain a JSON object.")
        if not isinstance(parsed.get("GroupAssessment"), dict) or not isinstance(parsed.get("Participants"), list):
            raise ValueError("The AI response is missing required group or participant sections.")
        return parsed

    try:
        return _parse_report_json(raw), None
    except Exception as first_parse_error:
        # One repair attempt prevents a nearly complete assessment from being discarded
        # when the model adds a fence, trailing text, or minor JSON formatting errors.
        try:
            repair_prompt = f"""Convert the following attempted GD assessment into STRICT VALID JSON only.
Do not change, invent, remove, or summarize assessment content. Fix JSON syntax/escaping only.
The top-level object must contain GroupAssessment (object) and Participants (array).

ATTEMPTED RESPONSE:
{str(raw)[:28000]}"""
            repaired_raw = get_groq_response(repair_prompt)
            repaired_report = _parse_report_json(repaired_raw)
            return repaired_report, None
        except Exception as repair_error:
            # Do not dump a large malformed report into the student's UI.
            return None, (
                "The AI returned an invalid assessment format and automatic repair failed. "
                "Please retry once. If it repeats, share the timestamp with the administrator. "
                f"(Parse: {type(first_parse_error).__name__}; repair: {type(repair_error).__name__})"
            )


def _gd_audio_sha256(audio_path):
    """Hash normalized extracted audio so identical recordings share one cache entry."""
    digest = hashlib.sha256()
    with open(audio_path, "rb") as audio_file:
        for chunk in iter(lambda: audio_file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _get_cached_gd_diarization(audio_sha256):
    """Return previously saved diarisation segments and split notes, if available."""
    conn = None
    try:
        conn = get_db_connection()
        row = conn.execute(
            "SELECT segments_json, split_notes_json FROM gd_diarization_cache WHERE audio_sha256=?",
            (audio_sha256,),
        ).fetchone()
        if not row:
            return None
        segments = json.loads(row["segments_json"] or "[]")
        split_notes = json.loads(row["split_notes_json"] or "[]")
        if not isinstance(segments, list) or not segments:
            return None
        return segments, split_notes if isinstance(split_notes, list) else []
    except Exception as exc:
        # A cache outage must never block the existing diarisation workflow.
        st.warning(f"Saved GD transcript cache could not be checked; continuing with normal diarisation. ({type(exc).__name__})")
        return None
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _save_cached_gd_diarization(audio_sha256, segments, split_notes):
    """Persist successful diarisation for reuse across sessions and duplicate uploads."""
    conn = None
    try:
        conn = get_db_connection()
        conn.execute(
            """
            INSERT INTO gd_diarization_cache
                (audio_sha256, model, segments_json, split_notes_json, created_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(audio_sha256) DO UPDATE SET
                model=excluded.model,
                segments_json=excluded.segments_json,
                split_notes_json=excluded.split_notes_json,
                created_at=excluded.created_at
            """,
            (
                audio_sha256,
                "gpt-4o-transcribe-diarize",
                json.dumps(segments, ensure_ascii=False),
                json.dumps(split_notes or [], ensure_ascii=False),
                activity_timestamp_now(),
            ),
        )
        conn.commit()
        return True
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        # Cache persistence is an optimization; don't discard a valid transcript.
        st.warning(f"GD diarisation completed, but its reusable cache could not be saved. ({type(exc).__name__})")
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def save_gd_video_assessment(scholar_id, topic, participants, segments, report, video_filename, source_type="Video GD"):
    """Persist a GD report, retrying once if PostgreSQL drops the SSL connection.

    The timestamp is generated once and reused as a lightweight idempotency key.
    If the connection drops during COMMIT, the next connection checks whether the
    report was already committed before attempting another INSERT.
    """
    duration_seconds = 0.0
    try:
        ends = [float(seg.get("end", 0) or 0) for seg in (segments or []) if isinstance(seg, dict)]
        starts = [float(seg.get("start", 0) or 0) for seg in (segments or []) if isinstance(seg, dict)]
        if source_type == "AI Voice GD":
            duration_seconds = sum(float(seg.get("duration_sec", 0) or 0) for seg in (segments or []) if isinstance(seg, dict))
        elif ends:
            duration_seconds = max(0.0, max(ends) - (min(starts) if starts else 0.0))
    except Exception:
        duration_seconds = 0.0

    stored_report = dict(report or {})
    stored_report.setdefault("SourceType", source_type)
    created_at = activity_timestamp_now()
    scholar_id = str(scholar_id or "").strip().upper()
    payload = (
        scholar_id, topic,
        json.dumps(participants, ensure_ascii=False),
        json.dumps(segments, ensure_ascii=False),
        json.dumps(stored_report, ensure_ascii=False),
        video_filename, duration_seconds, created_at,
    )

    last_error = None
    max_attempts = 2 if DATABASE_URL else 1
    for attempt in range(max_attempts):
        conn = None
        try:
            conn = get_db_connection()

            # A previous COMMIT may have succeeded even if its SSL response was lost.
            existing_row = conn.execute(
                "SELECT id FROM gd_assessments WHERE scholar_id=? AND created_at=? AND video_filename=? ORDER BY id DESC LIMIT 1",
                (scholar_id, created_at, video_filename),
            ).fetchone()
            if existing_row:
                conn.close()
                return existing_row["id"]

            conn.execute("""
                INSERT INTO gd_assessments
                (scholar_id, topic, participant_names, transcript_json, report_json, video_filename, duration_seconds, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, payload)
            saved_row = conn.execute(
                "SELECT id FROM gd_assessments WHERE scholar_id=? AND created_at=? AND video_filename=? ORDER BY id DESC LIMIT 1",
                (scholar_id, created_at, video_filename),
            ).fetchone()
            gd_grade, gd_summary, gd_feedback = _gd_report_score_and_feedback(stored_report)
            _insert_student_activity(
                conn, scholar_id=scholar_id, activity_type="Group Discussion",
                activity_timestamp=created_at, grade=gd_grade,
                summary=f"{topic or 'Group Discussion'} — {gd_summary}",
                duration_seconds=duration_seconds, feedback={"SourceType": source_type, **gd_feedback},
                source_table="gd_assessments", source_record_id=(saved_row["id"] if saved_row else uuid.uuid4().hex),
            )
            conn.commit()
            result_id = saved_row["id"] if saved_row else None
            conn.close()
            return result_id
        except Exception as save_error:
            last_error = save_error
            if conn is not None:
                try:
                    conn.rollback()
                except Exception:
                    pass
                try:
                    conn.close()
                except Exception:
                    pass

            transient_pg_error = DATABASE_URL and POSTGRES_AVAILABLE and isinstance(
                save_error, (psycopg2.OperationalError, psycopg2.InterfaceError)
            )
            if not transient_pg_error or attempt + 1 >= max_attempts:
                raise
            # Re-open a fresh pooled connection on the next iteration. No AI work
            # is repeated; only the short database persistence transaction retries.
            time.sleep(0.25)

    if last_error:
        raise last_error


def get_gd_video_assessments(scholar_id):
    conn = get_db_connection()
    try:
        rows = conn.execute("""
            SELECT * FROM gd_assessments
            WHERE scholar_id=?
            ORDER BY id DESC
        """, (scholar_id,)).fetchall()
        result = []
        for row in rows:
            item = dict(row)
            for key in ("participant_names", "transcript_json", "report_json"):
                try:
                    item[key] = json.loads(item.get(key) or "[]")
                except Exception:
                    item[key] = [] if key != "report_json" else {}
            result.append(item)
        return result
    finally:
        conn.close()


def get_ai_voice_gd_assessments(scholar_id):
    """Return only AI Voice GD practice assessments for student dashboards.

    Legacy uploaded-video GD records remain in the database for backward compatibility,
    but the student-facing GD workflow and progress dashboards use AI Voice GD only.
    """
    assessments = get_gd_video_assessments(scholar_id)
    result = []
    for item in assessments:
        report = item.get("report_json") or {}
        source_type = str(item.get("source_type") or report.get("SourceType") or "").strip().lower()
        if source_type == "ai voice gd" or report.get("SourceType") == "AI Voice GD":
            result.append(item)
    return result


def _base64url_json(value):
    raw = json.dumps(value, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def create_video_engine_token(student, room_code, expires_minutes=15):
    """Create a short-lived HS256 JWT without adding another Python dependency."""
    if not VIDEO_ENGINE_JWT_SECRET:
        return None

    now = int(time.time())
    payload = {
        "studentId": str(student.get("id") or student.get("student_id") or student.get("scholar_id")),
        "firstName": str(student.get("first_name", "")),
        "lastName": str(student.get("last_name", "")),
        "scholarId": str(student.get("scholar_id", "")),
        "email": str(student.get("email", "")).lower(),
        "roomId": str(room_code).upper(),
        "iat": now,
        "exp": now + (expires_minutes * 60),
        "iss": "iper-placement-portal"
    }
    header = {"alg": "HS256", "typ": "JWT"}
    encoded_header = _base64url_json(header)
    encoded_payload = _base64url_json(payload)
    signing_input = f"{encoded_header}.{encoded_payload}".encode("ascii")
    signature = hmac.new(
        VIDEO_ENGINE_JWT_SECRET.encode("utf-8"),
        signing_input,
        digestmod="sha256"
    ).digest()
    encoded_signature = base64.urlsafe_b64encode(signature).rstrip(b"=").decode("ascii")
    return f"{encoded_header}.{encoded_payload}.{encoded_signature}"


def render_inbuilt_gd_room(room_code, student, is_host=False, started_at=None):
    """Render the IPER-owned WebRTC room hosted by the separate video-engine service."""
    if not VIDEO_ENGINE_URL:
        st.error("The IPER Video Engine URL is not configured yet.")
        st.info("Add VIDEO_ENGINE_URL to Streamlit Secrets after deploying the video_engine service.")
        return

    if not VIDEO_ENGINE_JWT_SECRET:
        st.error("The IPER Video Engine security key is not configured yet.")
        st.info("Add VIDEO_ENGINE_JWT_SECRET to Streamlit Secrets. It must exactly match JWT_SECRET on the video engine service.")
        return

    token = create_video_engine_token(student, room_code, expires_minutes=15)
    if not token:
        st.error("Could not create a secure video-room access token.")
        return

    query = urllib.parse.urlencode({
        "room": str(room_code).upper(),
        "token": token,
        "firstName": student.get("first_name", ""),
        "lastName": student.get("last_name", ""),
        "scholarId": student.get("scholar_id", ""),
        "email": student.get("email", "")
    })
    room_url = f"{VIDEO_ENGINE_URL}/gd_room.html?{query}"
    display_name = f"{student.get('first_name', '')} {student.get('last_name', '')}".strip()
    role_label = "Student Host" if is_host else "Student Participant"

    st.markdown(f"""
    <div style="font-family:Inter,Arial,sans-serif;border:1px solid #CBD5E1;border-radius:12px;overflow:hidden;background:#0F172A;">
      <div style="padding:13px 16px;color:white;background:#0F172A;display:flex;justify-content:space-between;align-items:center;gap:12px;">
        <div><b>IPER PEPTECH Virtual GD Room</b><br><span style="font-size:12px;opacity:.85">{role_label} • {display_name} • maximum 7 students • maximum 10 minutes</span></div>
        <div style="font-size:12px;font-weight:700;color:#93C5FD;">IPER PEPTECH WebRTC</div>
      </div>
    </div>
    """, unsafe_allow_html=True)

    st.link_button(" Open IPER PEPTECH Virtual GD Room", room_url, use_container_width=True)
    st.caption("The secure room opens in a new browser tab so the camera and microphone can be granted directly to the IPER video service. Your name and Scholar ID are taken from your logged-in profile.")

    # Also provide an embedded view for browsers that allow camera/microphone access
    # inside the Streamlit component frame.
    components.html(f"""
    <div style="width:100%;height:720px;border:1px solid #CBD5E1;border-radius:12px;overflow:hidden;background:#0B1020;">
      <iframe
        src="{room_url}"
        title="IPER PEPTECH Virtual GD Room"
        allow="camera; microphone; fullscreen; display-capture"
        style="width:100%;height:100%;border:0;"
        allowfullscreen>
      </iframe>
    </div>
    """, height=735, scrolling=False)

def get_gd_ai_guidance(topic, student_name):
    prompt = f"""
You are an MBA Group Discussion coach at IPER Bhopal. Student name: {student_name}.
The student selected this GD topic: {topic}
Provide guidance, NOT a memorised speech. Cover exactly:
1. Topic interpretation
2. Arguments supporting the proposition
3. Arguments opposing the proposition
4. Business/economic perspective
5. Social perspective
6. Technology/future perspective
7. Indian context
8. Stakeholder perspectives
9. Three smart points a student could raise
10. Three questions a student could ask another participant
11. A balanced way to conclude
Use concise bullets and encourage listening and building on others' points.
"""
    return get_groq_response(prompt)


